                    fontSize: "0.75rem",
                    fontWeight: 600,
                    borderRadius: "9999px",
                    backgroundColor: product.available ? "#d1fae5" : "#fee2e2",
                    color: product.available ? "#065f46" : "#991b1b",
                  }}>
                    {product.available ? "Active" : "Inactive"}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div style={{ marginTop: "1rem", display: "flex", gap: "1rem", fontSize: "0.875rem", color: "#6b7280" }}>
        <span>{products.length} products</span>
        <span>•</span>
        <span>Cache tag: "products"</span>
      </div>
    </div>
  );
}

